// Test 1
[Fact]
public void J2024_IstSchaltjahr()
    => Assert.True(
        Jahr.IstSchaltjahr(2024));

// Code nach Runde 1 (grün)
static bool IstSchaltjahr(int j)
    => true;

// nach Runde 4: alle Tests grün
static bool IstSchaltjahr(int j)
    => j % 4 == 0
       && (j % 100 != 0
           || j % 400 == 0);

// Refactor: Tests zur Theory
// zusammenfassen
[Theory]
[InlineData(2024, true)]
[InlineData(2023, false)]
[InlineData(1900, false)]
[InlineData(2000, true)]
public void Schaltjahr(int j, bool e)
    => Assert.Equal(e,
        Jahr.IstSchaltjahr(j));
